303: function findAimTarget(origin, direction) {
304:   const cone = Math.cos((touchUi ? 13.5 : 7.5) * Math.PI / 180);
305:   let best = null;
306:   let bestDot = cone;
307:   for (const zombie of zombies) {
308:     if (zombie.dead) continue;
309:     const targetX = zombie.x - origin.x;
310:     const targetY = zombie.root.position.y + 1.12 - origin.y;
311:     const targetZ = zombie.z - origin.z;
312:     const distance = Math.hypot(targetX, targetY, targetZ);
313:     if (distance > state.weapon.range || distance < 0.8) continue;
314:     const dot = (targetX * direction.x + targetY * direction.y + targetZ * direction.z) / distance;
315:     if (dot > bestDot) {
316:       bestDot = dot;
317:       best = zombie;
318:     }
319:   }
320:   return best;
321: }
