416: function createFences(lines) {
417:   const postTransforms = [];
418:   const railTransforms = [];
419:   const up = new THREE.Vector3(0, 1, 0);
420:   const quaternion = new THREE.Quaternion();
421:   const matrix = new THREE.Matrix4();
422:   const position = new THREE.Vector3();
423:   const scale = new THREE.Vector3(1, 1, 1);
424: 
425:   for (const [startX, startZ, endX, endZ] of lines) {
426:     const dx = endX - startX;
427:     const dz = endZ - startZ;
428:     const length = Math.hypot(dx, dz);
429:     const pieces = Math.max(1, Math.round(length / 2));
430:     const rotation = Math.atan2(-dz, dx);
431:     for (let i = 0; i <= pieces; i += 1) {
432:       const t = i / pieces;
433:       const x = startX + dx * t;
434:       const z = startZ + dz * t;
435:       position.set(x, terrainHeight(x, z) + 0.54, z);
436:       matrix.compose(position, quaternion.identity(), scale);
437:       postTransforms.push(matrix.clone());
438:     }
439:     for (let i = 0; i < pieces; i += 1) {
440:       const t0 = i / pieces;
441:       const t1 = (i + 1) / pieces;
442:       const midX = startX + dx * (t0 + t1) / 2;
443:       const midZ = startZ + dz * (t0 + t1) / 2;
444:       const yaw = new THREE.Quaternion().setFromAxisAngle(up, rotation);
445:       for (const height of [0.48, 0.84]) {
446:         position.set(midX, terrainHeight(midX, midZ) + height, midZ);
447:         matrix.compose(position, yaw, scale);
448:         railTransforms.push(matrix.clone());
449:       }
450:     }
451:   }
452: 
453:   const postMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(0.14, 1.06, 0.14), material.fence, postTransforms.length);
454:   postTransforms.forEach((transform, index) => postMesh.setMatrixAt(index, transform));
455:   postMesh.castShadow = QUALITY === 'high';
456:   scene.add(postMesh);
457: 
458:   const railMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(2.02, 0.1, 0.055), material.fence, railTransforms.length);
459:   railTransforms.forEach((transform, index) => railMesh.setMatrixAt(index, transform));
460:   railMesh.castShadow = QUALITY === 'high';
461:   scene.add(railMesh);
462: }
