658: .crosshair i:nth-child(1) { top: 0; }
659: .crosshair i:nth-child(2) { bottom: 0; }
660: .crosshair i:nth-child(3), .crosshair i:nth-child(4) { width: 7px; height: 1px; top: 50%; }
