664: .crosshair span {
665:   position: absolute;
666:   top: 50%;
667:   left: 50%;
668:   width: 2px;
669:   height: 2px;
670:   border-radius: 50%;
671:   background: rgba(236, 226, 202, 0.95);
672:   transform: translate(-50%, -50%);
673: }
