323: function tryFire() {
324:   const now = clockNow();
325:   if (!state.started || state.paused || state.ended || state.reloading) return;
326:   if (now - state.lastShot < state.weapon.fireDelay * 1000) return;
327:   if (state.mag <= 0) {
328:     audio.empty();
329:     startReload();
330:     return;
331:   }
332: 
333:   state.lastShot = now;
334:   state.mag -= 1;
335:   refreshAmmo();
336:   audio.shoot(state.weapon.id);
337:   state.shake = Math.min(0.42, state.shake + (state.weapon.id === 'rifle' ? 0.27 : 0.13));
338:   state.pitch = clamp(state.pitch + (state.weapon.id === 'rifle' ? 0.024 : 0.009), -0.27, 0.54);
339:   muzzleTimer = 0.055;
340:   player.muzzleFlash.visible = true;
341:   player.muzzleFlash.rotation.z = Math.random() * Math.PI;
342:   document.body.classList.add('firing');
343:   window.setTimeout(() => document.body.classList.remove('firing'), 90);
344: 
345:   computeAimDirection();
346:   player.root.rotation.y = Math.atan2(aimDir.x, aimDir.z);
347:   shotOrigin.set(
348:     player.root.position.x,
349:     player.root.position.y + 1.34,
350:     player.root.position.z,
351:   ).addScaledVector(aimDir, 0.42);
352: 
353:   const target = findAimTarget(shotOrigin, aimDir);
354:   if (target) {
355:     shotEnd.set(target.x, target.root.position.y + 1.12, target.z);
356:     const result = damageZombie(target, state.weapon.damage, shotEnd);
357:     if (result.killed) {
358:       state.kills += 1;
359:       showToast('INFECTED DOWN', 'good');
360:     }
361:     showHitmarker(result.killed);
362:   } else {
363:     raycaster.set(shotOrigin, aimDir);
364:     raycaster.far = state.weapon.range + 35;
365:     raycasterTargets.length = 0;
366:     if (terrainMesh) raycasterTargets.push(terrainMesh);
367:     for (const mesh of houseMeshes) raycasterTargets.push(mesh);
368:     const hits = raycaster.intersectObjects(raycasterTargets, true);
369:     if (hits.length > 0) {
370:       shotEnd.copy(hits[0].point);
371:       spawnDust(shotEnd);
372:     } else {
373:       shotEnd.copy(shotOrigin).addScaledVector(aimDir, state.weapon.range + 30);
374:     }
375:   }
376: 
377:   muzzleWorld.set(0.35, 1.22, state.weapon.id === 'rifle' ? 1.46 : 0.77);
378:   player.root.localToWorld(muzzleWorld);
379:   spawnTracer(muzzleWorld, shotEnd);
380:   alertZombies(player.root.position.x, player.root.position.z, 35);
381: 
382:   if (state.mag === 0) {
383:     window.setTimeout(() => {
384:       if (state.started && !state.ended && !state.reloading) startReload();
385:     }, 260);
386:   }
387: }
