259: export function updateZombies(dt, context) {
260:   const playerPosition = context.player.root.position;
261:   const night = context.night;
262:   const targetSpeedMultiplier = night ? 1.22 : 1;
263: 
264:   for (let i = zombies.length - 1; i >= 0; i -= 1) {
265:     const zombie = zombies[i];
266: 
267:     if (zombie.dead) {
268:       zombie.deadTime += dt;
269:       zombie.root.rotation.x = Math.min(1.42, zombie.root.rotation.x + dt * 3.8);
270:       if (zombie.deadTime > 4.5) {
271:         zombie.root.position.y -= dt * 0.5;
272:       }
273:       if (zombie.deadTime > 7) {
274:         scene.remove(zombie.root);
275:         scene.remove(zombie.bar.background);
276:         scene.remove(zombie.bar.fill);
277:         zombies.splice(i, 1);
278:       }
279:       continue;
280:     }
281: 
282:     zombie.barTimer = Math.max(0, zombie.barTimer - dt);
283:     zombie.growlTimer -= dt;
284:     zombie.attackCooldown = Math.max(0, zombie.attackCooldown - dt);
285: 
286:     const dx = playerPosition.x - zombie.x;
287:     const dz = playerPosition.z - zombie.z;
288:     const distance = Math.hypot(dx, dz);
289: 
290:     if (distance < 21) zombie.alerted = true;
291:     if (distance > 33) zombie.alerted = false;
292: 
293:     let moveX = 0;
294:     let moveZ = 0;
295:     let speed = 0;
296: 
297:     if (zombie.alerted) {
298:       if (distance > 1.18) {
299:         const strafe = Math.sin(context.elapsed * 2.1 + zombie.phase) * 0.22;
300:         moveX = dx / (distance || 1) + strafe * (dz / (distance || 1));
301:         moveZ = dz / (distance || 1) - strafe * (dx / (distance || 1));
302:         speed = zombie.speedBase * targetSpeedMultiplier;
303:       } else if (zombie.attackCooldown <= 0) {
304:         zombie.attackCooldown = 1.05 + worldRandom() * 0.45;
305:         context.onAttack(7 + Math.floor(worldRandom() * 7), zombie);
306:         zombie.growlTimer = 1.4;
307:       }
308:       if (zombie.growlTimer <= 0 && distance < 17) {
309:         zombie.growlTimer = 5 + worldRandom() * 8;
310:         audio.growl();
311:       }
312:     } else {
313:       zombie.wanderTimer -= dt;
314:       if (zombie.wanderTimer <= 0) {
315:         zombie.wanderTimer = 3 + worldRandom() * 6;
316:         zombie.wanderAngle = worldRandom() * TAU;
317:       }
318:       moveX = Math.cos(zombie.wanderAngle);
319:       moveZ = Math.sin(zombie.wanderAngle);
320:       speed = 0.42;
321:     }
322: 
323:     if (speed > 0) {
324:       const length = Math.hypot(moveX, moveZ) || 1;
325:       moveX /= length;
326:       moveZ /= length;
327:       zombie.x += moveX * speed * dt;
328:       zombie.z += moveZ * speed * dt;
329:       resolvePosition(zombie, 0.36);
330:       zombie.facing = dampAngle(zombie.facing, Math.atan2(moveX, moveZ), 6.5, dt);
331:       zombie.phase += dt * speed * 3.3;
332:     }
333: 
334:     zombie.root.position.set(zombie.x, terrainHeight(zombie.x, zombie.z), zombie.z);
335:     zombie.root.rotation.y = zombie.facing;
336: 
337:     const swing = Math.sin(zombie.phase) * (zombie.alerted ? 0.74 : 0.38);
338:     zombie.legs[0].rotation.x = swing;
339:     zombie.legs[1].rotation.x = -swing;
340:     const armBase = -1.18;
341:     zombie.arms[0].rotation.x = armBase + Math.sin(zombie.phase + 0.8) * 0.12;
342:     zombie.arms[1].rotation.x = armBase + Math.sin(zombie.phase + 2.1) * 0.12;
343:     zombie.body.position.y = Math.abs(Math.sin(zombie.phase)) * 0.035;
344:     zombie.body.rotation.z = Math.sin(zombie.phase * 0.5) * 0.035;
345:     zombie.head.rotation.z = Math.sin(zombie.phase * 0.37 + zombie.phase) * 0.1;
