150: function updateCamera(dt) {
151:   if (!state.started) {
152:     const angle = elapsed * 0.034 + 0.3;
153:     camera.position.set(
154:       Math.sin(angle) * 33,
155:       11.6 + Math.sin(angle * 0.72) * 1.5,
156:       Math.cos(angle) * 33 - 8,
157:     );
158:     camera.lookAt(0, 2.5, -9);
159:     if (Math.abs(camera.fov - 62) > 0.01) {
160:       camera.fov = damp(camera.fov, 62, 4, dt);
161:       camera.updateProjectionMatrix();
162:     }
163:     return;
164:   }
165: 
166:   camTarget.set(player.root.position.x, player.root.position.y + 1.36, player.root.position.z);
167:   camForward.set(-Math.sin(state.yaw), 0, -Math.cos(state.yaw));
168:   camRight.set(Math.cos(state.yaw), 0, -Math.sin(state.yaw));
169: 
170:   const distance = touchUi ? 5.55 : 5.85;
171:   const shoulder = touchUi ? 0.62 : 0.76;
172:   camDesired.copy(camTarget)
173:     .addScaledVector(camForward, -distance)
174:     .addScaledVector(camRight, shoulder);
175:   camDesired.y += 1.55 + Math.sin(state.pitch) * 1.4;
176: 
177:   const groundAtCamera = terrainHeight(camDesired.x, camDesired.z) + 0.6;
178:   if (camDesired.y < groundAtCamera) camDesired.y = groundAtCamera;
179: 
180:   camDirection.copy(camDesired).sub(camTarget);
181:   const cameraDistance = camDirection.length();
182:   camDirection.normalize();
183:   raycaster.set(camTarget, camDirection);
184:   raycaster.far = cameraDistance;
185:   const hits = raycaster.intersectObjects(houseMeshes, true);
186:   if (hits.length > 0) {
187:     const safeDistance = Math.max(1.4, hits[0].distance - 0.28);
188:     camDesired.copy(camTarget).addScaledVector(camDirection, safeDistance);
189:   }
190: 
191:   const rate = state.elapsed < 1.25 ? 5.2 : 11.5;
192:   camera.position.lerp(camDesired, 1 - Math.exp(-rate * dt));
193: 
194:   const shake = state.shake;
195:   if (shake > 0.0005) {
196:     camera.position.x += (Math.random() - 0.5) * shake;
197:     camera.position.y += (Math.random() - 0.5) * shake * 0.7;
198:     camera.position.z += (Math.random() - 0.5) * shake;
199:     state.shake *= Math.exp(-7.5 * dt);
200:   }
201: 
202:   camLook.copy(camTarget)
203:     .addScaledVector(camForward, 8.5)
204:     .addScaledVector(camRight, shoulder);
205:   camLook.y += Math.sin(state.pitch) * 8.5;
206:   camera.lookAt(camLook);
207: 
208:   const sprinting = sprintHeld() && isMoving() && state.stamina > 1;
209:   const targetFov = sprinting ? 67 : 62;
210:   if (Math.abs(camera.fov - targetFov) > 0.02) {
211:     camera.fov = damp(camera.fov, targetFov, 7, dt);
212:     camera.updateProjectionMatrix();
213:   }
214: }
