220: function updatePlayer(dt) {
221:   const movement = getMovement();
222:   const sprinting = sprintHeld() && movement.moving && state.stamina > 0.5;
223:   let speed = movement.moving ? (sprinting ? 5.72 : 3.15) : 0;
224:   const inWater = isPondWater(player.root.position.x, player.root.position.z);
225:   if (inWater) speed *= 0.54;
226: 
227:   if (movement.moving) {
228:     camForward.set(-Math.sin(state.yaw), 0, -Math.cos(state.yaw));
229:     camRight.set(Math.cos(state.yaw), 0, -Math.sin(state.yaw));
230:     let moveX = camForward.x * movement.forward + camRight.x * movement.strafe;
231:     let moveZ = camForward.z * movement.forward + camRight.z * movement.strafe;
232:     const length = Math.hypot(moveX, moveZ) || 1;
233:     moveX /= length;
234:     moveZ /= length;
235: 
236:     player.root.position.x += moveX * speed * dt;
237:     player.root.position.z += moveZ * speed * dt;
238:     resolvePosition(player.root.position, 0.36);
239: 
240:     const facing = Math.atan2(moveX, moveZ);
241:     player.root.rotation.y = dampAngle(player.root.rotation.y, facing, 12, dt);
242:     walkPhase += dt * speed * 2.7;
243:     state.stepAccumulator += dt * (sprinting ? 2.2 : 1.15);
244:     if (state.stepAccumulator > 0.78) {
245:       state.stepAccumulator = 0;
246:       audio.footstep(sprinting);
247:     }
248:   } else if (state.fireHeld) {
249:     aimDir.set(
250:       -Math.sin(state.yaw) * Math.cos(state.pitch),
251:       Math.sin(state.pitch),
252:       -Math.cos(state.yaw) * Math.cos(state.pitch),
253:     );
254:     player.root.rotation.y = dampAngle(
255:       player.root.rotation.y,
256:       Math.atan2(aimDir.x, aimDir.z),
257:       9,
258:       dt,
259:     );
260:     state.stepAccumulator = 0;
261:   } else {
262:     state.stepAccumulator = 0;
263:   }
264: 
265:   const ground = inWater
266:     ? Math.max(terrainHeight(player.root.position.x, player.root.position.z), WATER_LEVEL - 1.18)
267:     : terrainHeight(player.root.position.x, player.root.position.z);
268:   player.root.position.y = damp(player.root.position.y, ground, 18, dt);
269: 
270:   if (sprinting) {
271:     state.stamina = Math.max(0, state.stamina - dt * 24);
272:   } else {
273:     state.stamina = Math.min(100, state.stamina + dt * (movement.moving ? 9 : 16));
274:   }
275:   ui.sprintBtn.classList.toggle('active', sprinting);
276: 
277:   const intensity = movement.moving ? (sprinting ? 0.95 : 0.68) : 0;
278:   const swing = Math.sin(walkPhase) * intensity;
279:   const idle = Math.sin(elapsed * 1.8) * (movement.moving ? 0 : 0.035);
280:   player.legL.rotation.x = swing + idle;
281:   player.legR.rotation.x = -swing - idle;
282:   player.armL.rotation.x = -swing * 0.7 + idle;
283:   player.armR.rotation.x = swing * 0.4 + (state.fireHeld ? -0.55 : 0);
284:   player.body.position.y = movement.moving ? Math.abs(Math.sin(walkPhase)) * 0.045 : Math.sin(elapsed * 1.6) * 0.012;
285:   player.body.rotation.z = movement.moving ? Math.sin(walkPhase) * 0.018 : 0;
286:   player.head.rotation.y = movement.moving ? Math.sin(walkPhase * 0.38) * 0.07 : Math.sin(elapsed * 0.6) * 0.06;
287:   player.head.rotation.x = Math.sin(elapsed * 1.15) * 0.012;
