294: function computeAimDirection() {
295:   aimDir.set(
296:     -Math.sin(state.yaw) * Math.cos(state.pitch),
297:     Math.sin(state.pitch),
298:     -Math.cos(state.yaw) * Math.cos(state.pitch),
299:   ).normalize();
300:   return aimDir;
