531:   const wellDistance = Math.hypot(position.x - WELL.x, position.z - WELL.z);
532:   if (wellDistance < 3.35 && (!nearest || wellDistance < nearest.distance)) {
533:     nearest = { type: 'well', distance: wellDistance };
