573: function updateSurvival(dt) {
574:   state.hurtCooldown = Math.max(0, state.hurtCooldown - dt);
575:   state.useCooldown = Math.max(0, state.useCooldown - dt);
576:   state.hunger = Math.max(0, state.hunger - dt * 0.33);
577:   state.thirst = Math.max(0, state.thirst - dt * 0.41);
578: 
579:   const starving = state.hunger <= 0;
580:   const dehydrated = state.thirst <= 0;
581:   if (starving || dehydrated) {
582:     const damage = (starving ? 0.5 : 0) + (dehydrated ? 0.55 : 0) + (starving && dehydrated ? 0.35 : 0);
583:     state.health = Math.max(0, state.health - dt * damage);
584:     if (state.health <= 0) endGame(false);
585:   } else if (state.health < 100 && state.hunger > 48 && state.thirst > 42) {
586:     state.health = Math.min(100, state.health + dt * 0.22);
587:   }
588: 
589:   if (state.health < 30) {
590:     state.heartTimer -= dt;
591:     if (state.heartTimer <= 0) {
592:       state.heartTimer = 1.25;
593:       audio.heartbeat();
594:     }
595:   } else {
596:     state.heartTimer = 0;
597:   }
598: 
599:   state.zombieSpawnTimer -= dt;
600:   if (state.zombieSpawnTimer <= 0) {
601:     const hour = ((state.gameHour % 24) + 24) % 24;
602:     const night = hour >= 20 || hour < 6;
603:     const limit = state.zombieLimit + (night ? 3 : 0);
604:     const alive = zombies.reduce((count, zombie) => count + (zombie.dead ? 0 : 1), 0);
605:     if (alive < limit) spawnZombieNear(player.root.position, 29, 47);
606:     state.zombieSpawnTimer = night ? 10 + Math.random() * 7 : 16 + Math.random() * 10;
607:   }
608: }
