614: function startGame() {
615:   if (state.started) return;
616:   state.started = true;
617:   state.elapsed = 0;
618:   state.gameHour = 17.5;
619:   audio.init();
620:   document.body.classList.add('playing');
621:   ui.hud.inert = false;
622:   ui.hud.setAttribute('aria-hidden', 'false');
623:   ui.start.classList.add('is-leaving');
624:   window.setTimeout(() => ui.start.classList.add('hidden'), 900);
625:   window.setTimeout(() => {
626:     if (!state.ended) {
627:       showLocation();
628:       showToast('SCAVENGE · SURVIVE UNTIL DAWN', 'good');
629:     }
630:   }, 500);
631:   aimHintTimeout = window.setTimeout(() => {
632:     if (state.started && !state.paused && !state.ended && document.pointerLockElement !== ui.canvas) {
633:       showAimHint();
634:     }
635:   }, 2600);
636:   updateNear(true);
637:   refreshAmmo();
638:   refreshInventory();
639:   updateHud();
640: }
641: 
642: function togglePause() {
643:   if (!state.started || state.ended) return;
644:   if (state.paused) {
645:     resumeGame();
646:     return;
647:   }
648:   state.paused = true;
649:   releaseInput();
650:   hideAimHint();
651:   setInteract(null);
652:   ui.pause.classList.remove('hidden');
653:   if (document.pointerLockElement) document.exitPointerLock();
654: }
655: 
656: function resumeGame() {
657:   if (!state.started || state.ended || !state.paused) return;
658:   state.paused = false;
659:   ui.pause.classList.add('hidden');
660:   lastFrame = performance.now();
661:   updateNear(true);
662: }
663: 
664: function toggleSound() {
665:   audio.init();
666:   const muted = audio.toggle();
667:   state.soundOn = !muted;
668:   updateSoundButton();
669:   showToast(muted ? 'SOUND OFF' : 'SOUND ON');
670: }
671: 
672: function endGame(won) {
673:   if (state.ended) return;
674:   state.ended = true;
675:   state.won = won;
676:   state.fireHeld = false;
677:   releaseInput();
678:   setReloadRing(false);
679:   setInteract(null);
680:   hideAimHint();
681:   clearTimeout(aimHintTimeout);
682:   document.body.classList.add('ended');
683:   if (won) audio.win();
684:   else audio.lose();
685:   if (document.pointerLockElement) document.exitPointerLock();
686:   window.setTimeout(() => showEndScreen(won), won ? 550 : 900);
687: }
