714:    Frame loop
715: -------------------------------------------------------------------------- */
716: 
717: function animateCampfires() {
718:   for (const fire of campFires) {
719:     const flicker = 0.82
720:       + Math.sin(elapsed * 9.2 + fire.phase) * 0.1
721:       + Math.sin(elapsed * 21.7 + fire.phase * 2) * 0.05;
722:     fire.flame.scale.set(0.88 + flicker * 0.18, flicker, 0.88 + flicker * 0.18);
723:     fire.flame.rotation.y = elapsed * 0.7 + fire.phase;
724:     fire.core.scale.setScalar(0.82 + flicker * 0.16);
725:     fire.light.intensity = (QUALITY === 'low' ? 1.05 : 1.65) * flicker;
726:   }
727: }
728: 
729: function loop(now) {
730:   requestAnimationFrame(loop);
731:   const dt = Math.min(0.05, Math.max(0, (now - lastFrame) / 1000));
732:   lastFrame = now;
733:   elapsed += dt;
734: 
735:   updateEnvironment(state.gameHour, elapsed);
736:   animateClouds(elapsed);
737:   animateCampfires();
738:   updateLoot(elapsed, dt);
739: 
740:   if (state.started && !state.paused && !state.ended) {
741:     state.elapsed += dt;
742:     state.gameHour += dt * (24 / DAY_SECONDS);
743:     updatePlayer(dt);
744:     const hour = ((state.gameHour % 24) + 24) % 24;
745:     updateZombies(dt, {
746:       player,
747:       night: hour >= 20 || hour < 6,
748:       elapsed: state.elapsed,
749:       onAttack: (damage) => hurtPlayer(damage),
750:     });
751:     updateSurvival(dt);
752:     updateReload(dt);
753:     updateNear();
754:     if (state.fireHeld) tryFire();
755:     if (!state.ended && state.gameHour >= DAWN_HOUR) endGame(true);
756:   }
757: 
758:   if (muzzleTimer > 0) {
759:     muzzleTimer -= dt;
760:     if (muzzleTimer <= 0) player.muzzleFlash.visible = false;
761:   }
762: 
763:   if (dust) {
764:     dust.position.x = damp(dust.position.x, player.root.position.x, 1.8, dt);
765:     dust.position.z = damp(dust.position.z, player.root.position.z, 1.8, dt);
766:     dust.position.y = player.root.position.y + 2.6;
767:     dust.rotation.y += dt * 0.014;
768:   }
769: 
770:   updateEffects(dt);
771:   updateCamera(dt);
772:   updateCompass(state.yaw);
773: 
774:   uiAccumulator -= dt;
775:   if (uiAccumulator <= 0) {
776:     uiAccumulator = 0.075;
777:     updateHud();
778:   }
779: 
780:   renderer.render(scene, camera);
781: }
782: 
783: updateEnvironment(state.gameHour, 0);
784: updateHud();
